-- seed part 01 · settings (6) + template_categories (15) — run first, in order
on conflict (key) do update set value = excluded.value;

on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, hero_description = excluded.hero_description, image = excluded.image, seo_title = excluded.seo_title, seo_description = excluded.seo_description, og_image = excluded.og_image, active = excluded.active, sort_order = excluded.sort_order;
